   328	 */
   329	function addMembersToWorkspace(invitedEmailsToAccountIDs, welcomeNote, policyID) {
   330	    const membersListKey = `${ONYXKEYS.COLLECTION.POLICY_MEMBERS}${policyID}`;
   331	    const logins = _.map(_.keys(invitedEmailsToAccountIDs), (memberLogin) => OptionsListUtils.addSMSDomainIfPhoneNumber(memberLogin));
   332	    const accountIDs = _.values(invitedEmailsToAccountIDs);
   333	    const newPersonalDetailsOnyxData = PersonalDetailsUtils.getNewPersonalDetailsOnyxData(logins, accountIDs);
   334	
   335	    // create onyx data for policy expense chats for each new member
   336	    const membersChats = createPolicyExpenseChats(policyID, invitedEmailsToAccountIDs);
   337	
   338	    const optimisticData = [
   339	        {
   340	            onyxMethod: Onyx.METHOD.MERGE,
   341	            key: membersListKey,
   342	
   343	            // Convert to object with each key containing {pendingAction: ‘add’}
   344	            value: _.object(accountIDs, Array(accountIDs.length).fill({pendingAction: CONST.RED_BRICK_ROAD_PENDING_ACTION.ADD})),
   345	        },
   346	        ...newPersonalDetailsOnyxData.optimisticData,
   347	        ...membersChats.onyxOptimisticData,
   348	    ];
   349	
   350	    const successData = [
   351	        {
   352	            onyxMethod: Onyx.METHOD.MERGE,
   353	            key: membersListKey,
   354	
   355	            // Convert to object with each key clearing pendingAction, when it is an existing account.
   356	            // Remove the object, when it is a newly created account.
   357	            value: _.reduce(
   358	                accountIDs,
   359	                (accountIDsWithClearedPendingAction, accountID) => {
   360	                    let value = null;
   361	                    const accountAlreadyExists = !_.isEmpty(allPersonalDetails[accountID]);
   362	
   363	                    if (accountAlreadyExists) {
   364	                        value = {pendingAction: null, errors: null};
   365	                    }
   366	
   367	                    // eslint-disable-next-line no-param-reassign
   368	                    accountIDsWithClearedPendingAction[accountID] = value;
   369	
   370	                    return accountIDsWithClearedPendingAction;
   371	                },
   372	                {},
   373	            ),
   374	        },
   375	        ...newPersonalDetailsOnyxData.successData,
   376	        ...membersChats.onyxSuccessData,
   377	    ];
   378	
   379	    const failureData = [
   380	        {
   381	            onyxMethod: Onyx.METHOD.MERGE,
   382	            key: membersListKey,
   383	
   384	            // Convert to object with each key containing the error. We don’t
   385	            // need to remove the members since that is handled by onClose of OfflineWithFeedback.
   386	            value: _.object(
   387	                accountIDs,
   388	                Array(accountIDs.length).fill({
   389	                    errors: ErrorUtils.getMicroSecondOnyxError('workspace.people.error.genericAdd'),
   390	                }),
   391	            ),
   392	        },
   393	        ...newPersonalDetailsOnyxData.failureData,
   394	        ...membersChats.onyxFailureData,
   395	    ];
   396	
   397	    const params = {
   398	        employees: JSON.stringify(_.map(logins, (login) => ({email: login}))),
   399	
   400	        // Do not escape HTML special chars for welcomeNote as this will be handled in the backend.
   401	        // See https://github.com/Expensify/App/issues/20081 for more details.
   402	        welcomeNote,
   403	        policyID,
   404	    };
   405	    if (!_.isEmpty(membersChats.reportCreationData)) {
   406	        params.reportCreationData = JSON.stringify(membersChats.reportCreationData);
   407	    }
   408	    API.write('AddMembersToWorkspace', params, {optimisticData, successData, failureData});
   409	}
